function handleChange(e){e.stopPropagation();let t=e.target.value;setDefaultOption("action");e.target.value=t;console.log("selected value: "+t);const n=e.currentTarget.closest(".group");t=t.toUpperCase();switch(t){case"UPDATE":setInfosStatus(n,true);n.querySelector(".update-tool").classList.add("active");break;case"INFO":var o=n.querySelector(".id").innerText;showInfo(o,"info");setDefaultOption("action");break;case"LOCK":{setInfosStatus(n,false);var o=n.querySelector(".id").innerText;setupConfirm(o,"#lock-confirm-modal",o);break}case"UNLOCK":{setInfosStatus(n,false);var o=n.querySelector(".id").innerText;setupConfirm(o,"#unlock-confirm-modal",o);break}case"DELETE":{setInfosStatus(n,false);var o=n.querySelector(".id").innerText;setupConfirm(o,"#delete-confirm-modal",o);break}case"DESCRIPTION":{var o=n.querySelector(".id").innerText;showDescription(o);break}case"UPDATEDETAIL":{setInfosStatus(document.querySelector("#infoTable"),false);if(document.querySelector("#infoTable .btn-update-detail.active"))document.querySelector("#infoTable .btn-update-detail.active").classList.remove("active");setInfosStatus(n,true);n.querySelector(".btn-update-detail").classList.add("active");break}case"LOCKDETAIL":{setInfosStatus(n,false);var r=n.querySelector("input[name='classify']").value;var o=n.querySelector(".id").innerText;var a="Phân loại: ID: "+o+" - "+r;setupConfirm(o,"#lock-detail-confirm-modal",a);break}case"ACTIVEDETAIL":{setInfosStatus(n,false);var r=n.querySelector("input[name='classify']").value;var o=n.querySelector(".id").innerText;var a="Phân loại: ID: "+o+" - "+r;setupConfirm(o,"#unlock-detail-confirm-modal",a);break}case"DELETEDETAIL":{setInfosStatus(n,false);var r=n.querySelector("input[name='classify']").value;var o=n.querySelector(".id").innerText;var a="Phân loại: ID: "+o+" - "+r;setupConfirm(o,"#delete-detail-confirm-modal",a);break}case"OTHER-CATEGORY":{console.log(document.querySelector("#addProductForm .other-category-input"));addActive("#addProductForm .other-category-input");addActive("#updateInfoForm .other-category-input");n.querySelector("input[name='other-category']").value="Khác";break}case"DONGTRUNG":case"NAM":case"RUOU":{removeActive("#addProductForm .other-category-input");removeActive("#updateInfoForm .other-category-input");n.querySelector("input[name='other-category']").value="";break}default:setInfosStatus(n,false)}}function setupConfirm(e,t,n){openModal(t);document.querySelector(t).querySelector(".object").innerText=n;document.querySelector(t).querySelector('input[name="id"]').value=e}function lock(e){var t=e.currentTarget.closest(".group").querySelector('input[name="id"]').value;$.ajax({type:"POST",url:"avoucher?a=lock",data:{id:t},success:function(e){$("#avoucher-response").html(e);hideModal("#lock-confirm-modal");setDefaultOption("action")},error:function(e){$("#avoucher-response").html(e.responseText)}})}function active(e){var t=e.currentTarget.closest(".group").querySelector('input[name="id"]').value;$.ajax({type:"POST",url:"avoucher?a=active",data:{id:t},success:function(e){$("#avoucher-response").html(e);hideModal("#unlock-confirm-modal");setDefaultOption("action")},error:function(e){$("#avoucher-response").html(e.responseText)}})}function deleteVoucher(e){var t=e.currentTarget.closest(".group").querySelector('input[name="id"]').value;$.ajax({type:"POST",url:"avoucher?a=delete",data:{id:t},success:function(e){$("#avoucher-response").html(e);hideModal("#delete-confirm-modal")},error:function(e){$("#avoucher-response").html(e.responseText)}})}function setDefaultOption(e){document.querySelectorAll('select[name="'+e+'"]').forEach((e=>{const t=e.getAttribute("data-default");e.value=t}))}function saveUpdate(e){const t=e.currentTarget.closest(".group");const n=t.querySelector(".id").innerText;const o=t.querySelector('input[name="discount"]').value;const r=t.querySelector('input[name="maxMoney"]').value;const a=t.querySelector('input[name="qty"]').value;const c=t.querySelector('input[name="startTime"]').value;const s=t.querySelector('input[name="endTime"]').value;update(n,o,r,a,c,s).then((function(n){renderInfoRow(n);showSuccessToast2("Cập nhật thành công.","none");cancelUpdate(e,t)})).catch((function(e){showErrorToast2("Không thể tải thông tin: "+e.responseText,"none")}))}function update(e,t,n,o,r,a){return new Promise(((c,s)=>{$.ajax({url:"avoucher?a=update",type:"POST",data:{id:e,discount:t,maxMoney:n,qty:o,startTime:r,endTime:a},dataType:"json",success:function(e){c(e)},error:function(e){s(e)}})}))}function renderInfoRow(e){const t=document.querySelector("#infoTable tbody");const n=t.querySelectorAll("tr");for(let t=0;t<n.length;t++){if(n[t].id==="voucher"+e.id){const o=n[t];o.querySelector(".id").innerText=e.id;o.querySelector('input[name="discount"]').value=e.discount;o.querySelector('input[name="maxMoney"]').value=e.maxMoney;o.querySelector('input[name="qty"]').value=e.qty;o.querySelector('input[name="startTime"]').value=e.startTime;o.querySelector('input[name="endTime"]').value=e.endTime;break}}}function cancelUpdate(e,t){if(t==null)t=e.currentTarget.closest(".group");setInfosStatus(t,false);if(t.querySelector(".update-tool").classList.contains("active"))t.querySelector(".update-tool").classList.remove("active");setDefaultOption("action")}function saveUpdateDescription(e){const t=e.currentTarget.closest("form");const n=t.querySelector('input[name="id"]').value;const o=t.querySelector('textarea[name="description"]').value;$.ajax({url:"avoucher?a=updateDescription",type:"POST",data:{id:n,description:o},success:function(e){if(e==="true"){showSuccessToast2("Cập nhật thành công.","none")}else{showErrorToast2("Cập nhật thất bại.","none")}hideModal("#description-modal");setDefaultOption("action")},error:function(e){showErrorToast2("Cập nhật thất bại.","none")}})}function showDescription(e){getDescription(e).then((function(e){renderDescription(e)})).catch((function(e){showErrorToast2("Không thể tải thông tin: "+e.responseText,"none")}))}function getDescription(e){return new Promise(((t,n)=>{$.ajax({url:"avoucher?a=description",type:"POST",dataType:"json",data:{id:e},success:function(e){t(e)},error:function(e){n(e)}})}))}function renderDescription(e){const t=document.querySelector("#description-modal");t.classList.add("active");t.querySelector('input[name="id"]').value=e.id;t.querySelector('textarea[name="description"]').value=e.description}function renderAppliedProductList(e){const t=$("#appliedProductListTable tbody");t.empty();let n=0;e.forEach((function(e){var o=e.product;const r=`\n            <tr class="group" id="appliedProduct${o.id}">\n                <th scope="row" class="grid-col-0_5 text-center" >\n                    <span class="stt">${n++}</span>\n                </th>\n                <td class="grid-col-0_5 text-center product-id">\n                    <span class="id">${o.id}</span>\n                </td>\n                <td class="grid-col-0_5">\n                    <div class="img-thumbnail-container">\n                        <img src="./assets/img/thumbnail/${o.thumbnail}" alt="">\n                    </div>\n                </td>\n                <td class="grid-col-1_5">\n                    <span class="name">${o.name}</span>\n                </td>\n                <td class="grid-col-1">\n                    <span class="category">${o.category}</span>\n                </td>\n                <td class="grid-col-1" onclick="event.stopPropagation();">\n                    <button class="btn btn-primary" onclick="removeProduct(event)">Xóa</button>\n                </td>\n            </tr>\n        `;t.append(r)}))}function getAppliedProductList(e){return new Promise(((t,n)=>{$.ajax({url:"avoucher?a=appliedProducts",type:"POST",dataType:"json",data:{id:e},success:function(e){t(e)},error:function(e){n(e)}})}))}function showAppliedProductList(e){document.querySelector("#applied-product-list-modal").classList.add("active");getAppliedProductList(e).then((function(e){renderAppliedProductList(e)})).catch((function(e){showErrorToast2("Không thể tải thông tin: "+e.responseText,"none")}))}